// =============================================================================
// [VINYL ANGEL YOUTUBE PLAYLIST INGESTION LAB & 3-TIER DIAGNOSTIC STREAM]
// 🟢 Green:  All songs of that playlist are in DB (100% Synced)
// 🟡 Yellow: Playlist contains uncurled songs that are being/were curled
// 🔴 Red:    Songs failed to curl (playlist 404 or songs unavailable/private on YouTube)
// Output Target: backend/data/projects/music_app/app_data/system/_1_static.db
// =============================================================================
import React, { useState, useEffect, useRef, useCallback, useMemo } from 'react';
import { executeOrder } from '../../../services/api';
import {
  getCurlerPlaylists,
  saveCurlerPlaylists,
  streamPlaylistIngestion,
} from '../services/engine';
import type { CurlerStreamEvent, PlaylistReportItem } from '../types';
import {
  DownloadCloud,
  Terminal,
  Play,
  Square,
  Trash2,
  ListMusic,
  Database,
  CheckCircle2,
  AlertCircle,
  Sparkles,
  Save,
  X,
  Layers,
  Disc3,
  Sliders,
  Filter,
  Plus,
  ExternalLink,
  Link,
  Radio,
} from 'lucide-react';

interface VinylIngestionProps {
  projectId?: string;
  onNavigateToGameplay?: () => void;
  onNavigateToGallery?: () => void;
}

interface LogEntry {
  id: string;
  timestamp: string;
  type: string;
  message: string;
  category: 'green' | 'yellow' | 'red' | 'info';
}

function extractPlaylistId(url: string): string {
  const clean = url.trim();
  if (
    clean.startsWith('PL') ||
    clean.startsWith('UU') ||
    clean.startsWith('FL') ||
    clean.startsWith('RD')
  ) {
    return clean;
  }
  try {
    const parsed = new URL(clean);
    const list = parsed.searchParams.get('list');
    if (list) return list;
  } catch (_) {}
  const match = url.match(/[?&]list=([^#&?]+)/);
  if (match) return match[1];
  return clean.slice(0, 32);
}

export const VinylIngestion: React.FC<VinylIngestionProps> = ({
  projectId = 'music_app',
  onNavigateToGameplay,
  onNavigateToGallery,
}) => {
  const targetProjectId = !projectId || projectId === 'vinyl_angel' ? 'music_app' : projectId;

  // Telemetry state
  const [totalCatalogCount, setTotalCatalogCount] = useState<number>(0);
  const [playlists, setPlaylists] = useState<string[]>([]);
  const [targetDbName, setTargetDbName] = useState<string>('system/_1_static.db');

  // Diagnostic counts
  const [totalGreen, setTotalGreen] = useState<number>(0);
  const [totalYellow, setTotalYellow] = useState<number>(0);
  const [totalRed, setTotalRed] = useState<number>(0);

  // Execution state
  const [isRunning, setIsRunning] = useState<boolean>(false);
  const [currentProgress, setCurrentProgress] = useState<{ current: number; total: number }>({
    current: 0,
    total: 0,
  });
  const [totalScanned, setTotalScanned] = useState<number>(0);
  const [totalNewAdded, setTotalNewAdded] = useState<number>(0);
  const [finalReport, setFinalReport] = useState<PlaylistReportItem[]>([]);
  const [reportFilter, setReportFilter] = useState<'all' | 'green' | 'yellow' | 'red'>('all');

  // Logs state
  const [logs, setLogs] = useState<LogEntry[]>([]);
  const [autoScroll, setAutoScroll] = useState<boolean>(true);
  const terminalBottomRef = useRef<HTMLDivElement>(null);
  const abortControllerRef = useRef<AbortController | null>(null);

  // Playlist Manager Modal state
  const [showPlaylistModal, setShowPlaylistModal] = useState<boolean>(false);
  const [managerMode, setManagerMode] = useState<'interactive' | 'raw'>('interactive');
  const [newPlaylistInput, setNewPlaylistInput] = useState<string>('');
  const [rawPlaylistText, setRawPlaylistText] = useState<string>('');
  const [isSavingPlaylists, setIsSavingPlaylists] = useState<boolean>(false);
  const [modalPlaylists, setModalPlaylists] = useState<string[]>([]);

  const [toast, setToast] = useState<{ message: string; type: 'success' | 'error' | 'info' | 'warn' } | null>(
    null
  );

import json
import shutil
import sqlite3
from pathlib import Path
from datetime import datetime
from typing import Optional, Any, Dict, List
from fastapi import HTTPException
from pydantic import BaseModel

BACKEND_DIR = Path(__file__).resolve().parent.parent
BASE_DIR = BACKEND_DIR / "data" / "projects"
SPEC_PATH = BACKEND_DIR / "api_spec.json"

PROJECT_ALIASES: Dict[str, str] = {
    "vinyl_angel": "music_app",
    "universe-25": "universe_25",
    "golden_hour": "universe_25",
    "golden-hour": "universe_25",
    "modern_day": "universe_25",
    "modern-day": "universe_25",
}

def resolve_project_id(project_id: str) -> str:
    direct_path = BASE_DIR / project_id / "index.json"
    if direct_path.exists():
        return project_id
    if project_id in PROJECT_ALIASES:
        aliased_id = PROJECT_ALIASES[project_id]
        if (BASE_DIR / aliased_id / "index.json").exists():
            return aliased_id
    return project_id

def load_global_spec() -> Dict[str, Any]:
    if not SPEC_PATH.exists():
        raise HTTPException(status_code=500, detail=f"Missing configuration file api_spec.json at: {SPEC_PATH}")
    with open(SPEC_PATH, "r", encoding="utf-8") as f:
        return json.load(f)

def load_project_index(project_id: str) -> Dict[str, Any]:
    resolved_id = resolve_project_id(project_id)
    index_path = BASE_DIR / resolved_id / "index.json"
    if not index_path.exists():
        raise HTTPException(status_code=404, detail=f"Project '{project_id}' not found at: {index_path}")
    with open(index_path, "r", encoding="utf-8") as f:
        return json.load(f)

def write_error_log(project_id: str, message: str):
    try:
        resolved_id = resolve_project_id(project_id)
        log_dir = BASE_DIR / resolved_id / "logs"
        log_dir.mkdir(parents=True, exist_ok=True)
        with open(log_dir / "error.log", "a", encoding="utf-8") as f:
            f.write(f"[{datetime.now().isoformat()}] {message}\n")
    except Exception:
        pass

def infer_sqlite_column_type(val: Any) -> str:
    if isinstance(val, bool):
        return "INTEGER"
    if isinstance(val, int):
        return "INTEGER"
    if isinstance(val, float):
        return "REAL"
    return "TEXT"

def _parse_exclude_list(exclude_val: Any) -> List[str]:
    if not exclude_val:
        return []
    if isinstance(exclude_val, (list, set, tuple)):
        return [str(c).strip() for c in exclude_val if str(c).strip() and str(c).strip() not in ["NONE", "ALL"]]
    if isinstance(exclude_val, str):
        val = exclude_val.strip()
        if not val or val in ["NONE", "ALL"]:
            return []
        if (val.startswith("[") and val.endswith("]")) or (val.startswith("(") and val.endswith(")")):
            try:
                parsed = json.loads(val)
                if isinstance(parsed, list):
                    return [str(c).strip() for c in parsed if str(c).strip() and str(c).strip() not in ["NONE", "ALL"]]
            except Exception:
                pass
        if "," in val:
            parts = [p.strip() for p in val.split(",") if p.strip() and p.strip() not in ["NONE", "ALL"]]
            if parts:
                return parts
        return [val]
    return []

def _build_hazard_filter_clause(conn: sqlite3.Connection, app_data_dir: Path, hazard_cap: Any) -> Optional[str]:
    """
    Constructs an ultra-fast SQLite filter clause against _4_display.db (t4_db).
    _4_display.db is the single source of truth for hazard levels.
    All track IDs not present in _4_display.db are unrated tracks (baseline 3.0).
    """
    if hazard_cap is None:
        return None
    h_str = str(hazard_cap).strip().lower()
    if h_str in ["none", "all", "inf", "", "all tracks"]:
        return None

